EOF
cat > app/Http/Validators/CommentValidator.ts <<'EOF'
import { z } from 'zod'

export const CommentIdParamSchema = z.object({
  id: z.coerce.number().int().positive(),
})

export const CommentPayloadSchema = z.object({
  body: z.string().min(1, 'Comment is required.').max(2000, 'Comment must be 2000 characters or fewer.'),
